'use strict';
const menuButton=document.querySelector('.menu-toggle');
const navigation=document.querySelector('#main-navigation');
const header=document.querySelector('.site-header');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');navigation.classList.remove('is-open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));navigation.classList.toggle('is-open',open);});
navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
document.addEventListener('click',e=>{if(!header.contains(e.target))closeMenu();});
matchMedia('(min-width:901px)').addEventListener('change',closeMenu);
let scrollQueued=false;
addEventListener('scroll',()=>{if(scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{header.classList.toggle('is-sticky',scrollY>50);scrollQueued=false;});},{passive:true});
header.classList.toggle('is-sticky',scrollY>50);
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
if('IntersectionObserver' in window&&!motionPreference.matches){document.documentElement.classList.add('motion-ready');const entrance=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('is-visible');entrance.unobserve(entry.target);}}},{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>entrance.observe(el));}
if('IntersectionObserver' in window){const sectionObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){navigation.querySelectorAll('a[href^="#"]:not(.button)').forEach(a=>a.setAttribute('aria-current',String(a.hash==='#'+e.target.id)));}},{rootMargin:'-20% 0px -60% 0px'});document.querySelectorAll('main>section[id]').forEach(s=>sectionObserver.observe(s));}
const services=[...document.querySelectorAll('.service-list details')];
services.forEach((details,index)=>details.addEventListener('toggle',()=>{if(!details.open)return;for(const other of services)if(other!==details)other.open=false;const img=document.querySelector('#service-image');img.src='assets/'+details.dataset.image;img.alt=details.dataset.alt;document.querySelector('#service-caption').textContent=String(index+1).padStart(2,'0')+' / '+details.querySelector('h3').textContent.toUpperCase();}));
document.querySelectorAll('[data-service]').forEach(link=>link.addEventListener('click',()=>{const message=document.querySelector('#message');if(!message.value.trim())message.value=`I’d like to discuss ${link.dataset.service.toLowerCase()} for my space.\n\n`;message.dispatchEvent(new Event('input'));}));
const cards=[...document.querySelectorAll('.project-card')];let activeFilter='all',showAll=false;
function filterProjects(){let count=0;for(const card of cards){const match=activeFilter==='all'||card.dataset.categories.split(' ').includes(activeFilter);card.hidden=!match||(activeFilter==='all'&&!showAll&&card.hasAttribute('data-extra'));if(!card.hidden){count++;card.classList.add('is-visible');}}document.querySelector('#project-count').textContent=count+' of '+cards.length+' references';const toggle=document.querySelector('#view-projects');toggle.hidden=activeFilter!=='all';toggle.innerHTML=(showAll?'Show fewer spaces':'View all spaces')+' <span aria-hidden="true">↗</span>';}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));filterProjects();}));
document.querySelector('#view-projects').addEventListener('click',()=>{showAll=!showAll;filterProjects();});
const projects={living:{title:'The light-filled living room',category:'RESIDENTIAL / MODERN MINIMALIST',image:'gallery-living-dining.webp',alt:'Cream sectional sofa, rounded armchairs and a timber dining area framed by full-height curtains',description:'A living and dining reference in warm neutrals. A generous cream sectional, rounded armchairs and layered coffee tables sit alongside a timber-lined dining area, with soft daylight connecting the spaces.',source:'Supplied living and dining design reference'},kitchen:{title:'A quieter kind of kitchen',category:'RESIDENTIAL / KITCHEN',image:'kitchen.jpg',alt:'White minimalist kitchen with a warm timber floor',description:'A reference for restrained cabinetry, warm timber and a clear, practical layout. A starting point for conversations about storage, light and the rituals of cooking.',photographer:'Clay Banks',source:'https://unsplash.com/photos/avPVKD07Fcg'},lounge:{title:'The sculpted lounge',category:'RESIDENTIAL / LUXURY INTERIORS',image:'gallery-sculpted-lounge.webp',alt:'Curved ivory seating, sculptural coffee tables and a dining area with a dark timber bar',description:'A reference for sculptural seating and layered materials. Curved ivory sofas, rounded armchairs and contrasting coffee tables create a soft foreground, while a dining setting, dark timber bar and warm cove lighting bring depth to the room.',source:'Supplied lounge design reference'},workspace:{title:'Room for a fresh perspective',category:'COMMERCIAL / WORKSPACE',image:'workspace.jpg',alt:'Bright contemporary office interior',description:'A commercial reference for a light-filled work environment. Open sightlines and comfortable shared areas offer a starting point for planning how people meet, focus and move.',photographer:'Deliberate Directions',source:'https://unsplash.com/photos/yTrgkVaY1TM'}};
const dialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const project=projects[button.dataset.project];const img=document.querySelector('#dialog-image');img.src='assets/'+project.image;img.alt=project.alt;document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-category').textContent=project.category;document.querySelector('#dialog-description').textContent=project.description;const source=document.querySelector('#dialog-source');source.replaceChildren();if(project.photographer){const a=document.createElement('a');a.href=project.source;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Photo: '+project.photographer+' / Unsplash';source.append(a);}else source.textContent=project.source;dialog.showModal();document.body.classList.add('modal-open');}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
document.querySelector('#dialog-enquire').addEventListener('click',()=>dialog.close());
document.querySelector('#year').textContent=new Date().getFullYear();


